<?php
namespace App\Filament\Resources;
use App\Filament\Resources\CustomerResource\Pages;use App\Models\MarketingSource;use Filament\Resources\Forms\Components;use Filament\Resources\Forms\Form;use Filament\Resources\Resource;use Filament\Resources\Tables\Columns;use Filament\Resources\Tables\Filter;use Filament\Resources\Tables\Table;
class CustomerResource extends Resource{public static $icon='heroicon-o-user-group';public static $label='Khách hàng';public static $navigationLabel='Khách hàng';public static $navigationSort=10;
public static function form(Form $f){return $f->schema([Components\TextInput::make('customer_code')->label('Mã khách hàng')->placeholder('Hệ thống tự sinh sau khi lưu')->disabled(),Components\TextInput::make('full_name')->label('Họ tên')->required(),Components\TextInput::make('phone')->label('Điện thoại')->required(),Components\TextInput::make('email')->label('Email')->email(),Components\Select::make('customer_type')->label('Loại khách')->options(['individual'=>'Cá nhân','company'=>'Công ty'])->required(),Components\TextInput::make('company_name')->label('Tên công ty'),Components\TextInput::make('tax_code')->label('Mã số thuế'),Components\Select::make('source_id')->label('Nguồn marketing')->options(MarketingSource::pluck('name','id')->toArray()),Components\Textarea::make('initial_address')->label('Địa chỉ khách hàng')->placeholder('Nhập số nhà, tên đường, phường/xã, quận/huyện, tỉnh/thành phố')->required(),Components\Select::make('status')->label('Trạng thái')->options(['active'=>'Hoạt động','inactive'=>'Ngừng hoạt động','blocked'=>'Đã khóa'])->default('active')->required(),Components\Textarea::make('note')->label('Ghi chú')]);}
public static function table(Table $t){return $t->columns([Columns\Text::make('customer_code')->label('Mã KH')->primary()->searchable()->sortable(),Columns\Text::make('full_name')->label('Họ tên')->searchable()->sortable(),Columns\Text::make('phone')->label('Điện thoại')->searchable(),Columns\Text::make('customer_type')->label('Loại')->options(['individual'=>'Cá nhân','company'=>'Công ty']),Columns\Text::make('source.name')->label('Nguồn'),Columns\Text::make('water_purifiers_count')->label('Số máy'),Columns\Text::make('last_service_at')->label('DV gần nhất')->date('d/m/Y'),Columns\Text::make('next_service_at')->label('DV tiếp theo')->date('d/m/Y'),Columns\Text::make('status')->label('Trạng thái')->options(['active'=>'Hoạt động','inactive'=>'Ngừng','blocked'=>'Khóa']),Columns\Text::make('created_at')->label('Ngày tạo')->dateTime('d/m/Y H:i')])->filters([Filter::make('active',fn($q)=>$q->where('status','active'))->label('Đang hoạt động'),Filter::make('company',fn($q)=>$q->where('customer_type','company'))->label('Công ty'),Filter::make('due',fn($q)=>$q->whereNotNull('next_service_at')->whereDate('next_service_at','<=',today()))->label('Đến hạn dịch vụ')]);}
public static function relations(){return[\App\Filament\Resources\Customer\RelationManagers\AddressesRelationManager::class,\App\Filament\Resources\Customer\RelationManagers\WaterPurifiersRelationManager::class,\App\Filament\Resources\Customer\RelationManagers\ServiceOrdersRelationManager::class];}public static function routes(){return[Pages\ListCustomers::routeTo('/','index'),Pages\CreateCustomer::routeTo('/create','create'),Pages\EditCustomer::routeTo('/{record}/edit','edit')];}}
